'use strict';
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('chosen',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-sector]').forEach(card=>{card.hidden=value!=='all'&&card.dataset.sector!==value;if(!card.hidden)card.classList.add('in-view')})}));
const scenarios={clinica:{name:'OdontoViva',kind:'Clínica odontológica',mark:'OV',color:'#237f78',prompt:'Olá! Bem-vindo à OdontoViva. Como podemos ajudar?',services:['Conhecer os cuidados','Simular uma avaliação','Falar com a equipe'],detail:'Neste exemplo, a clínica apresenta prevenção, estética do sorriso e reabilitação. Para orientações individuais, a conversa segue com a equipe.',goal:'Avaliação odontológica',slots:['Terça · 10:00','Quarta · 14:30','Quinta · 16:00']},restaurante:{name:'Casa Brasa',kind:'Restaurante',mark:'CB',color:'#995232',prompt:'Olá! Que bom receber você na Casa Brasa. O que gostaria de explorar?',services:['Conhecer o menu','Simular uma reserva','Falar com a equipe'],detail:'Nosso menu demonstrativo inclui costela de fogo lento, peixe na brasa e entradas para compartilhar.',goal:'Reserva de mesa',slots:['Sexta · 19:00','Sábado · 20:00','Domingo · 12:30']},empresa:{name:'BGTech Consulting',kind:'Serviços digitais',mark:'BG',color:'#3566a9',prompt:'Olá! Qual é o próximo passo para o seu negócio?',services:['Conhecer as soluções','Simular uma conversa','Falar com a equipe'],detail:'A BGTech desenvolve sites, sistemas personalizados e automações de atendimento. Qualquer proposta começa com uma conversa sobre o seu negócio.',goal:'Conversa sobre projeto',slots:['Segunda · 09:00','Terça · 15:00','Quarta · 11:00']}};
let chatSession=0;
function chatDemo(){const token=++chatSession;const body=document.querySelector('#demo-body');document.querySelector('#demo-dialog').classList.add('support-dialog');body.innerHTML=`<div class="support-lab"><aside class="support-sidebar"><div class="lab-brand"><span>BG</span><div>Central de atendimento<small>EXPERIÊNCIA DEMONSTRATIVA</small></div></div><p class="sidebar-label">ESCOLHA UM CENÁRIO</p><div class="scenario-list">${Object.entries(scenarios).map(([id,s])=>`<button data-scenario="${id}"><span class="business-avatar" style="background:${s.color}">${s.mark}</span><span>${s.name}<small>${s.kind}</small></span><i>›</i></button>`).join('')}</div><div class="request-summary"><span class="sidebar-label">RESUMO DA SOLICITAÇÃO</span><div id="request-summary"><p>Escolha um cenário e inicie a conversa.</p></div></div><div class="sidebar-note"><span>◈</span><p>Do primeiro contato<br>ao atendimento humano.</p></div></aside><section class="support-thread"><header class="thread-head"><div class="business-avatar" id="thread-avatar">OV</div><div><strong id="thread-name">OdontoViva</strong><small><i></i> Assistente demonstrativo</small></div><button id="restart-chat" aria-label="Reiniciar conversa">↺</button></header><div class="thread-messages" role="log" aria-live="polite" aria-label="Conversa demonstrativa"></div><div class="reply-area"><div class="reply-options" aria-label="Respostas sugeridas"></div><form class="message-form"><label class="sr-only" for="chat-text">Sua mensagem de exemplo</label><input id="chat-text" autocomplete="off" maxlength="250" placeholder="Digite uma mensagem de exemplo…"><button type="submit" aria-label="Enviar mensagem na simulação">↑</button></form><small class="simulation-label">SIMULAÇÃO LOCAL · RESPOSTAS PREDEFINIDAS · SEM ENVIO DE DADOS</small></div></section></div>`;
let selected='clinica',step='start',busy=false,session=0,summary={},timers=[];
const log=body.querySelector('.thread-messages'),options=body.querySelector('.reply-options'),form=body.querySelector('.message-form'),input=body.querySelector('#chat-text');
function active(){return token===chatSession&&document.querySelector('#demo-dialog').open&&body.contains(log)}
function clearTimers(){timers.forEach(clearTimeout);timers=[];busy=false}
function setSummary(){const box=body.querySelector('#request-summary');box.replaceChildren();for(const [key,value]of Object.entries(summary)){const dl=document.createElement('div');const label=document.createElement('small');label.textContent=key;const val=document.createElement('strong');val.textContent=value;dl.append(label,val);box.append(dl)}}
function bubble(text,user=false){const b=document.createElement('div');b.className='thread-bubble'+(user?' sent':' received');const p=document.createElement('p');p.textContent=text;const time=document.createElement('small');time.textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+(user?' · ✓✓':'');b.append(p,time);log.append(b);log.scrollTop=log.scrollHeight}
function replies(items){options.replaceChildren();items.forEach(item=>{const button=document.createElement('button');button.textContent=item;button.type='button';button.onclick=()=>receive(item);options.append(button)})}
function reply(text,items=[],after){busy=true;options.replaceChildren();const typing=document.createElement('div');typing.className='typing';typing.setAttribute('aria-label','Preparando resposta');typing.innerHTML='<i></i><i></i><i></i>';log.append(typing);log.scrollTop=log.scrollHeight;const local=session;timers.push(setTimeout(()=>{typing.remove();if(!active()||local!==session)return;bubble(text);busy=false;replies(items);if(after)after()},matchMedia('(prefers-reduced-motion:reduce)').matches?0:650))}
function start(id){clearTimers();session++;selected=id;step='start';const s=scenarios[id];summary={'Negócio':s.name,'Situação':'Conversa iniciada'};setSummary();body.style.setProperty('--chat-accent',s.color);body.querySelector('#thread-name').textContent=s.name;body.querySelector('#thread-avatar').textContent=s.mark;body.querySelectorAll('[data-scenario]').forEach(b=>{b.classList.toggle('active',b.dataset.scenario===id);b.setAttribute('aria-pressed',String(b.dataset.scenario===id))});log.replaceChildren();const day=document.createElement('div');day.className='thread-day';day.textContent='HOJE · CONVERSA DE EXEMPLO';log.append(day);bubble(s.prompt);replies(s.services);input.value=''}
function handoff(){step='done';summary['Situação']='Pronto para atendimento humano';setSummary();reply('Solicitação organizada. Em uma implementação real, a equipe receberia este resumo para continuar o atendimento.',[],()=>{const card=document.createElement('div');card.className='handoff-card';const title=document.createElement('strong');title.textContent='✓ Encaminhamento simulado';const p=document.createElement('p');p.textContent='Gostou da experiência? Converse com a BGTech sobre uma solução para seu negócio.';const a=document.createElement('a');a.textContent='Falar com a BGTech no WhatsApp ↗';a.className='support-cta';a.href='https://wa.me/5511920193443?text='+encodeURIComponent('Olá! Experimentei a demonstração de atendimento para '+scenarios[selected].kind.toLowerCase()+' e quero algo semelhante para meu negócio.');a.target='_blank';a.rel='noopener';card.append(title,p,a);log.append(card);log.scrollTop=log.scrollHeight;replies(['Reiniciar conversa'])})}
function receive(text){if(busy||!text.trim())return;input.value='';bubble(text,true);const s=scenarios[selected],normalized=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(normalized.includes('reiniciar')){start(selected);return}if(/equipe|humano|atendente/.test(normalized)){summary['Interesse']=summary['Interesse']||'Conversar com a equipe';handoff();return}if(step==='done'){reply('Esta simulação terminou. Você pode reiniciar ou escolher outro segmento.', ['Reiniciar conversa']);return}if(step==='slot'){const slot=s.slots.find(v=>v===text);if(!slot){reply('Escolha um dos horários ilustrativos abaixo para continuar.',s.slots);return}summary['Preferência']=slot;summary['Situação']='Aguardando confirmação';setSummary();step='confirm';reply('Resumo: '+s.goal+' · '+slot+'. Podemos simular o encaminhamento para a equipe?',['Confirmar solicitação','Escolher outro horário']);return}if(step==='confirm'){if(normalized.includes('outro')){step='slot';reply('Claro. Qual horário de exemplo você prefere?',s.slots);return}if(normalized.includes('confirm')||normalized==='sim'){handoff();return}reply('Para continuar, confirme a solicitação ou escolha outro horário.',['Confirmar solicitação','Escolher outro horário']);return}if(/simular|agend|reserva|avaliacao|conversa/.test(normalized)){summary['Interesse']=s.goal;summary['Situação']='Escolhendo horário';setSummary();step='slot';reply('Vamos simular '+s.goal.toLowerCase()+'. Escolha uma opção ilustrativa — nenhum horário será reservado de verdade.',s.slots);return}if(/conhecer|menu|solu|servic|cuidado/.test(normalized)){summary['Interesse']='Conhecer serviços';setSummary();reply(s.detail,[s.services[1],s.services[2]]);return}reply('Neste exemplo, posso apresentar os serviços, simular uma solicitação ou encaminhar para a equipe. Escolha uma opção para explorar.',s.services)}
form.onsubmit=e=>{e.preventDefault();receive(input.value)};body.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>start(b.dataset.scenario));body.querySelector('#restart-chat').onclick=()=>start(selected);start('clinica');}
document.querySelector('#demo-dialog').addEventListener('close',()=>{chatSession++;document.querySelector('#demo-dialog').classList.remove('support-dialog')});
